fn scrub_exact_max_length_not_truncated() {
    // Use "err! " to avoid matching token/hex/base64 regexes
    let chunk = "err! ";
    let repeats = MAX_ERROR_LENGTH / chunk.len();
    let input: String = chunk.repeat(repeats);
    assert_eq!(input.len(), MAX_ERROR_LENGTH);
    let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
